{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.Order_Over_Issues_real_v4 AS SELECT orders.ORDER_DATE, orders.daily_order_count, COALESCE(ticket_counts.daily_ticket_count, 0) AS daily_ticket_count, COALESCE(ticket_counts.daily_bot_correct, 0) AS daily_ticket_cust_message_count, COALESCE(ticket_countsb.daily_ticket_countb, 0) AS daily_agent_ticket_countb, COALESCE(ticket_countsb.Tag_contri, 0) AS daily_agent_ticket_countb2 FROM ( select COUNT(DISTINCT order_id) AS daily_order_count,date(ORDER_TIMESTAMP) as ORDER_DATE from snitch_db.maplemonk.fact_items_snitch where lower(ifnull(discount_code,\'n\')) not like \'%eco%\' and lower(ifnull(discount_code,\'n\')) not like \'%influ%\' and order_name not in (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') and tags not in (\'FLITS_LOGICERP\') AND ORDER_TIMESTAMP >= \'2024-07-01\' GROUP BY date(ORDER_TIMESTAMP) ) AS orders LEFT JOIN ( SELECT CAST(\"Created date\" AS date) AS Converted_Created_At, COUNT(DISTINCT \"External ticket Id\") AS daily_ticket_count, COUNT(DISTINCT CASE WHEN cust_message_count > 1 THEN \"External ticket Id\" END) AS daily_bot_correct FROM ( SELECT \"External ticket Id\", MIN(\"Created date\") AS \"Created date\", MIN(status) AS status, MIN(flow) AS flow FROM maplemonk.freshchat_bot_conversations WHERE CAST(\"Created date\" AS date) >= \'2024-10-01 00:00:00\' AND status = \'Closed\' AND flow NOT IN (\'Resolve - Campaigns flow\', \'Talk to agent\') GROUP BY \"External ticket Id\" ) A LEFT JOIN ( SELECT m.value:conversation_id::string AS \"External ticket id\", COUNT(DISTINCT m.value:id::string) AS total_message_count, COUNT(DISTINCT CASE WHEN m.value:actor_type::string = \'user\' THEN m.value:id::string END) AS cust_message_count FROM freshchat_msg_final_v3_conversations_by_id t, LATERAL FLATTEN(INPUT => t.messages) m GROUP BY m.value:conversation_id::string ) C ON A.\"External ticket Id\" = C.\"External ticket id\" GROUP BY CAST(\"Created date\" AS date) ) AS ticket_counts ON orders.ORDER_DATE = ticket_counts.Converted_Created_At LEFT JOIN ( SELECT A.created_date AS Converted_Created_Atb, COUNT(DISTINCT A.\"External ticket Id\") AS daily_ticket_countb, SUM(CASE WHEN C.TAG NOT IN (\'Comments\', \'Collaboration\', \'Post Share\', \'Story Mention\', \'Job Query\', \'Random Post Share\', \'Franchise\', \'Contest/Give Away/Coupon\', \'Advertisement Issue/Query\', \'Sponsorship\', \'Positive Feedback\', \'Wholesale Query\', \'Account Deactivation\', \'Invoice Request\', \'Fresh Fit Issue\', \'Test\',\'CNR / No query\', \'CNR\', \'General Query\', \'Campaign\', \'Mobile number update\', \'Email ID update\', \'Spam\', \'Ordered from third party\', \'Ambassador Program\', \'Relove Query\', \'Bot Drop off\') and C.TAG is not null THEN 1 ELSE 0 END) AS Tag_contri FROM ( SELECT DISTINCT \"External ticket Id\", DATE(\"Created date\") AS created_date FROM freshchat_bot_conversations WHERE FLOW = \'Talk to agent\' ) A LEFT JOIN ( SELECT DISTINCT CONVERSATION_ID, INTERACTION_RAW_ID FROM freshchat_conversation_activity ) B ON A.\"External ticket Id\" = B.CONVERSATION_ID LEFT JOIN ( SELECT DISTINCT INTERACTION_ALIAS, TAG FROM freshchat_frontent_old WHERE TAG IS NOT NULL and TAG != \'\' ) C ON B.INTERACTION_RAW_ID = C.INTERACTION_ALIAS GROUP BY A.created_date ) AS ticket_countsb ON orders.ORDER_DATE = ticket_countsb.Converted_Created_Atb CREATE OR REPLACE TABLE snitch_db.maplemonk.Order_Over_Issues_real_v3 AS SELECT orders.ORDER_DATE, orders.daily_order_count, COALESCE(ticket_counts.daily_ticket_count, 0) AS daily_ticket_count, COALESCE(ticket_countsb.daily_ticket_countb, 0) AS daily_ticket_countb, COALESCE((COALESCE(ticket_counts.daily_ticket_count, 0) * 100.0) / NULLIF(orders.daily_order_count, 0), 0) AS ticket_percentage, COALESCE((COALESCE(ticket_countsb.daily_ticket_countb, 0) * 100.0) / NULLIF(orders.daily_order_count, 0), 0) AS ticket_percentageb FROM ( SELECT COUNT(DISTINCT order_id) AS daily_order_count,date(ORDER_TIMESTAMP) as ORDER_DATE FROM maplemonk.fact_items_snitch WHERE shop_name IN (\'Shopify_India\') AND ORDER_TIMESTAMP >= \'2024-07-01\' GROUP BY date(ORDER_TIMESTAMP) ) AS orders LEFT JOIN ( SELECT CAST( \"Created date\" as date) AS Converted_Created_At, count(DISTINCT \"External ticket Id\") AS daily_ticket_count FROM maplemonk.freshchat_bot_conversations WHERE CAST( \"Created date\" as date) >= \'2024-07-01\' and status =\'Closed\' and flow not in ( \'Resolve - Campaigns flow\', \'Talk to agent\') GROUP BY CAST( \"Created date\" as date) ) AS ticket_counts ON orders.ORDER_DATE = ticket_counts.Converted_Created_At LEFT JOIN ( SELECT TO_DATE(resolved_at) AS Converted_Created_Atb, COUNT(DISTINCT interaction_id) AS daily_ticket_countb FROM snitch_db.maplemonk.freshchat_frontent_old WHERE TO_DATE(resolved_at) >= \'2024-07-01\' AND Tag NOT IN (\'Comments\', \'Collaboration\', \'Post Share\', \'Story Mention\', \'Job Query\', \'Random Post Share\', \'Franchise\', \'Contest/Give Away/Coupon\', \'Advertisement Issue/Query\', \'Sponsorship\', \'Positive Feedback\', \'Wholesale Query\', \'Account Deactivation\', \'Invoice Request\', \'Fresh Fit Issue\', \'Test\') GROUP BY TO_DATE(resolved_at) ) AS ticket_countsb ON orders.ORDER_DATE = ticket_countsb.Converted_Created_Atb ORDER BY orders.ORDER_DATE DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            